) AS (
  VALUES 
    (443::BIGINT, 'Fue muy injusto y poco claro con las evaluaciones, se excusa y revisa todo siempre con inteligencia artificial. Evalúa en exámenes y quices con cosas que nunca se han visto en clase. Cero flexible con entregas.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2026-08-13T00:00:00+00:00'::TIMESTAMPTZ, 'c323a08dc40d4425650c592377048a1d220f1208838449107225db538ddefd8d'::TEXT, ARRAY[1763]::BIGINT[]),
    (443::BIGINT, 'Lleve un curso con diogenes y uno con harold el mismo semestre, y puedo decir que preferi a Diogenes, claramente no regala el curso como harold, pero si se aprende bastante, nada más es aprender a ganarse al profe y repasar bien los exámenes viejos, tampoco es que el curso es imposible de pasarlo.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2026-06-30T00:00:00+00:00'::TIMESTAMPTZ, 'aa59d2e753b099c4ce88978514156c72b8ca82a1cdb2855544d4201964707782'::TEXT, ARRAY[1722]::BIGINT[]),
    (443::BIGINT, 'Hace el curso más difícil de lo que es, siempre calificando en contra del estudiante. Utiliza IA para absolutamente todo, incluso para dar la materia del curso y revisar los proyectos. Si valoran su salud mental, no lleven nada con él.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2026-06-09T00:00:00+00:00'::TIMESTAMPTZ, '9bcd4396ec7d4926b1fd2a0582ea8d3181c8f0711cf83940000d35f9dda4ee61'::TEXT, ARRAY[1722]::BIGINT[]),
    (443::BIGINT, 'Cero recomendado. Es una persona prepotente y cree que lo sabe todo. Da la impresión de que quiere que a uno le vaya mal, ya que nunca es claro con aspectos de evaluación y califica duro. En general, es un curso fácil pero con el una odisea.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos']::TEXT[], '2026-04-22T00:00:00+00:00'::TIMESTAMPTZ, 'ed52eac38b89848c0a8d7211d3589568e5ff4dde5d4fb1f799482f825c11b7e8'::TEXT, ARRAY[1722]::BIGINT[]),
    (443::BIGINT, 'Es grosero e incómodo por todo. Hace el curso súper difícil y califica duro, pero se pasa con exámenes viejos. Cuesta mucho contactarlo, mejor meta con Harold.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-12-09T00:00:00+00:00'::TIMESTAMPTZ, '5afe53bb060ac3af941e3b5b8b0cfe2e201cce4a048f5555c7506685c55b788c'::TEXT, ARRAY[1722]::BIGINT[]),
    (443::BIGINT, 'Este mae hace el curso más díficil de lo que es, él se cree god, super egocéntrico. Evalúa fatal, solo las respuestas y hace el curso para quedarse. Tiene que ponerle el triple para pasar esa vara. Busque los examenes anteriores, son los mismos siempre.'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2025-07-17T00:00:00+00:00'::TIMESTAMPTZ, '20f471a5b819b7999dc864f2c8c33cace2282d31754a75c56b5d1c5708f252f8'::TEXT, ARRAY[1722]::BIGINT[]),
    (443::BIGINT, 'TODO lo hace con CHATGPT. el proyecto ni lo revisa, solo lo mete en el chat y le lee lo que chat diga como si fuese santa palabra. Toma asistente DOS VECES en la clase, sigue siendo prepotente, no se le puede preguntar nada. Las asistentes son buenas calificando. No vale la pena llevar nada con él.'::TEXT, 8.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-07-05T00:00:00+00:00'::TIMESTAMPTZ, '1bd84922c25008edcf4608741f2b7c3cc10dd4c3a5e04336d4c31754d8e14a68'::TEXT, ARRAY[1746]::BIGINT[]),
    (443::BIGINT, 'El profe no sabe explicar bien y parece quese ofende cuando uno tiene una duda, da la sensación de que el profe piensa que uno lo está desafiando, al inicio del curso hace quices dificiles, se puede pasar estudiando y pero llevar clases con él es una complicación innecesaria.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2025-01-27T00:00:00+00:00'::TIMESTAMPTZ, '6d020d3b350aa546ce061a4559fc70a5082bcd358ebe17c178dfba74409fa017'::TEXT, ARRAY[1746]::BIGINT[]),
    (443::BIGINT, 'No logra dejar claros varios temas, pero en la práctica que se hace en clase es donde se termina de entender. Si llevan ya las soluciones de una práctica en clase, h no vale nada porque no entiende usted ni nadie, la práctica no vale nada. Hay que ponerle un toque al curso, pero es interesante'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2024-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'a8778098ccd88ef4a08d0c3ba94876ce0d583ed435d0ddecd9f4422e37776f32'::TEXT, ARRAY[1763]::BIGINT[]),
    (443::BIGINT, 'Hace el curso bastante pesa y dejaba un proyecto muy pesado en el cual habia que invertir mucho dinero, y no era un proyecto oficial, además, se dejaba todo y el dinero uno lo perdía. Lo rescatable del curso es que las asistentes califican suave y los examenes los califica suave entonces se pasa ok'::TEXT, 8.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos', 'Muchos proyectos grupales']::TEXT[], '2024-11-11T00:00:00+00:00'::TIMESTAMPTZ, '21a2d7e94138b274edb793029f33f13010c25c0a91f799b07c176452335cab11'::TEXT, ARRAY[1736]::BIGINT[]),
    (443::BIGINT, 'Egocéntrico, prepotente, le encanta hacer comentarios fuera de lugar y si uno le pregunta sobre alguna duda el mae lo toma como si uno lo estuviera cuestionando mas allá de intentar explicar. Todas las clases parece hablar de lo mismo y es pésimo a la hora de dar retroalimentación.'::TEXT, 8.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria']::TEXT[], '2024-10-07T00:00:00+00:00'::TIMESTAMPTZ, '10d384d5b7aabe802af60cae74bb3ea807efc26c4165fa194e2e695dda097d53'::TEXT, ARRAY[1736]::BIGINT[]),
    (443::BIGINT, 'Los temas del curso en si son faciles, por lo tanto el examen y quices igual. La matada es tareas y el proyecto, son pesados, complicados y se tienen que hacer cosas que no se aprende en clase (arduino), pero es una gran oportunidad para salir de la zona de comfort y usar el laboratorio de produ.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Pocos exámenes', 'Aspectos de calificación claros']::TEXT[], '2024-06-23T00:00:00+00:00'::TIMESTAMPTZ, '5efe12fb7104b1d05a34d7ef2a3af1cb8776065a27109a48549b9a9b5aa72236'::TEXT, ARRAY[1736]::BIGINT[]),
    (443::BIGINT, 'El peor profesor de la carrera, demasiado prepotente y en la exposición final le gusta humillar a los estudiantes y sus proyectos. No explica nada.Los temas del curso son muy importantes, no lo recomiendo para nada.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores']::TEXT[], '2024-06-22T00:00:00+00:00'::TIMESTAMPTZ, '29fcb30c5bac64884d4c210e51f990e3f083cbc0df1a2e068c46e57265fef5e2'::TEXT, ARRAY[1763]::BIGINT[]),
    (443::BIGINT, 'El profe intenta ser gracioso y muchas veces no le sale. Durante las clases pierde mucho tiempo y habla sobre cosas que nada que ver con los temas. Sus explicaciones tampoco son las mejores y no siempre está dispuesto a ayudar.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, '299ba9afbe8f558515623bfc75013e9201257ea7a2e0a1a6cb4de789f520134b'::TEXT, ARRAY[1722]::BIGINT[]),
    (443::BIGINT, 'Pocos quices y de sorpresa; si sale mal en uno, le afecta bastante la nota. El curso es bastante sencillo, el profe en general es buena nota o trata de serlo. La forma de explicar no es la mejor, pero igual se pasa fácil. Se aprende? Sí, pero se podría aprender mucho más si aprovechara mejor el time'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-11-28T00:00:00+00:00'::TIMESTAMPTZ, 'b148215a9364ff0f209ee6e61754e895e627525621d78ff282e0ff2eae9aa973'::TEXT, ARRAY[1722]::BIGINT[]),
    (443::BIGINT, '>Excelente Profesor'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-11-04T00:00:00+00:00'::TIMESTAMPTZ, '018dc522f23d260d257fcee2dfdeba49c20e5c6fcbd2c46b24f4847c1660c729'::TEXT, ARRAY[1763]::BIGINT[]),
    (443::BIGINT, 'Excelente profe. Explica bien aunque a veces puede ir muy rápido, con solo estudiar con las cosas de semestres pasados pasa bien. Califica la asistente y es muy suave con todo. El proyecto lo califica él pero también muy suave. Creo que es el mejor profe para este curso.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-25T00:00:00+00:00'::TIMESTAMPTZ, '0929badd0a34897e3a27d420030c559bae4c3d5d268df7ec915308083e384780'::TEXT, ARRAY[1763]::BIGINT[]),
    (443::BIGINT, 'El curso es bastante sencillo, recomiendo practicar con exámenes de semestres anteriores. Las clases son largas y aburridas, en ella el 30% es de la materia y el resto es hablar de las vivencias de él. El proyecto lo califica justo.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Asistencia obligatoria', 'Pocos exámenes']::TEXT[], '2023-06-25T00:00:00+00:00'::TIMESTAMPTZ, 'dbf2b3b33d9180178237c90c985c3fb3adc30edcbb93973960f8509122e54b07'::TEXT, ARRAY[1722]::BIGINT[]),
    (443::BIGINT, 'No enseña bien entonces el curso se vuleve muy autodidacta. Si uno va a consulta lo regaña a uno. Trabajos en grupo. Es un juega de vivo, prepotente y pasado con sus comentarios.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-19T00:00:00+00:00'::TIMESTAMPTZ, '3a1fae803e2710996edad56a3dd06cd04f5a04a99e3f193ab272bdffa05d5c72'::TEXT, ARRAY[1722]::BIGINT[]),
    (443::BIGINT, 'El peor profe. Es muy egocéntrico y se sale del tema cuando está explicando por empezar a hablar de él y sobre lo que ha hecho. No lo recomiendo.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2023-06-18T00:00:00+00:00'::TIMESTAMPTZ, '0c23534e2076c62ec332bacf1855480384dc4198222f8c1f60f1e6535450ead4'::TEXT, ARRAY[1722]::BIGINT[]),
    (443::BIGINT, 'Regala el curso, lo hace ver y sentir a uno como si fuera a ser la mayor matada de la vida pero no. El curso es facil, se sale de los temas del curso cuando explica pero en realidad es mas util lo que explica no relacionado con la materia que el curso entonces promete'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-18T00:00:00+00:00'::TIMESTAMPTZ, '9d7315d2c1a1af68ce9a6833fc505b43b5162e4a23c4c39df05c03d5a60bbd6b'::TEXT, ARRAY[1722]::BIGINT[]),
    (443::BIGINT, 'La asistente es quien califica todas las evaluaciones y califica muy suave. Estudie/practique quices y exámenes de semestres pasados y se pasa solo el curso. Las clases son largas pero entretenidas, el profe habla mucho de otros temas.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-06-13T00:00:00+00:00'::TIMESTAMPTZ, 'ba5702461dba92714950df900e2677ad834c66461a60dd9ebd9ef83b25dd42e9'::TEXT, ARRAY[1763]::BIGINT[]),
    (443::BIGINT, 'para este curso recomiendo hacer mucha práctica de semestres pasados. Las clases se pasan rápido.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Asistencia obligatoria', 'Exámenes retadores']::TEXT[], '2023-06-08T00:00:00+00:00'::TIMESTAMPTZ, '707cb7a7338039fa5576728f6ba14bb5ebafdeac4cac4d026ae03ef4754347a5'::TEXT, ARRAY[1763]::BIGINT[]),
    (443::BIGINT, 'Explica bien y da buena retroalimentación'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2023-06-03T00:00:00+00:00'::TIMESTAMPTZ, '6a4681a67fbd76aa72ee2a2b2792171f3f2518ad0bb3705fbc3918d790048e07'::TEXT, ARRAY[1736]::BIGINT[]),
    (443::BIGINT, 'Creo que es el mejor para este curso'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-05-30T00:00:00+00:00'::TIMESTAMPTZ, 'a3730c0f9fd06dbe114850a46d5599e8026d108d17912ab046159f258620ab23'::TEXT, ARRAY[1763]::BIGINT[]),
    (443::BIGINT, 'El curso es un asco, este profe le encanta humillar y hacer comentarios fuera de lugar. Si uno pregunta por un tema le dice "vea la grabación", solamente explica cuando toca presencial las clase. El trabajo final lo pone con formato de TFG de produ. No matriculen los sábados es un ERROR'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('50','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Muchos proyectos grupales']::TEXT[], '2023-04-22T00:00:00+00:00'::TIMESTAMPTZ, '9a63df5c36a8cd8c10f25bdafb6e3e9e6f2d308c15b7f15dec118a8e2f5db925'::TEXT, ARRAY[2536]::BIGINT[]),
    (443::BIGINT, 'Este mae es de produ, No tiene que estar en ATI dando clases un sábado a las 7 mae. Le encanta humillar, usar formato pechacucha para las expo, super estricto con los tiempos, espero nunca más verlo ni en la calle porque le voy a preguntar, viejo reduzcame los costos duro mucho, 7 segundos.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-03-03T00:00:00+00:00'::TIMESTAMPTZ, 'd9d865473abd5046e2b94484486772a6d8f618fee275b97e15c4286dfd9507a9'::TEXT, ARRAY[2538]::BIGINT[]),
    (443::BIGINT, 'El profe es buena gente, se aprende bastante y explica claro, pero jamás hay que llevar dos cursos el mismo día con él, porque sus proyectos son largos y deja varias tarea, y le gusta pedir todo para el mismo día, es decir, examen, avance y tarea, y eso x2 curso, muy agotador.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-02-08T00:00:00+00:00'::TIMESTAMPTZ, '0c9fdb140de3a36a414252dd667e2e809dc2cf14b4fbf316f6ed9eede52a61e7'::TEXT, ARRAY[1736]::BIGINT[]),
    (443::BIGINT, 'Él no califica nada, todo lo hace el asistente. Califica suave y es llevadero. Las clases las suele hacer entretenidas pero tiene un carácter complicado. Además, se nota la preferencia por compañeras bonitas'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-01-28T00:00:00+00:00'::TIMESTAMPTZ, 'a37c751e6fddfbcb44eb8f9f9876a55306fbdf09feb47bd8bd86727104759d0f'::TEXT, ARRAY[1763]::BIGINT[]),
    (443::BIGINT, 'Considero que es uy bueno dando este curso, la clase se pasa rapido y las evaluciones son sencillas. Se aprende bastante'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2023-01-25T00:00:00+00:00'::TIMESTAMPTZ, '21d4dfedb27bccbca41a3dcdd0848d362d9dd230935245dffbdac7b725896e8a'::TEXT, ARRAY[1722]::BIGINT[]),
    (443::BIGINT, 'No me parece buen profesor, muy rara la forma de dar clases, no se entiende cual es el hilo conductor. Los exámenes son completes con palabras TEXTUALES de las presentaciones. Proyecto largo y pesado, lo deja para el mismo día de los exámenes'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2022-11-20T00:00:00+00:00'::TIMESTAMPTZ, '9e5efe2c4504124223f07e8c320c888f5afd7d37a210d943c9a85cdbb99d61b9'::TEXT, ARRAY[2538]::BIGINT[]),
    (443::BIGINT, 'El profe es pura vida, se aprende bastante. Debo decir que los exámenes tienen una dificultad un poco alta. El proyecto lo califica suave. Las clases son muy cómicas, lo volvería a llevar el curso con él. Hace varios quices.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2022-11-19T00:00:00+00:00'::TIMESTAMPTZ, '6975e3e8a8e811dab85126ee9c95c0aeac81920dd42619b3b12c4b8ea2a8a139'::TEXT, ARRAY[1763]::BIGINT[]),
    (443::BIGINT, 'Cuando quiere, puede humillarte. Es estricto con el tiempo en las presentaciones que uno tenga que hacer. Tiene que aprenderse las diapositivas tal cual para los exámenes (pregunta PALABRAS específicas). La evaluación es incongruente: 50% exámenes, 15% tareas y quinces y 25% un proyecto (tesis)'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2022-11-19T00:00:00+00:00'::TIMESTAMPTZ, 'acf8fea491925c25c753f91be22d93a19d3277f4ae72e4d1d8874459c5a8a989'::TEXT, ARRAY[2538]::BIGINT[]),
    (443::BIGINT, 'Tiene sus momentos de ser malo malo, mala persona; peeero como profe siento que uno aprende. Examenes complicados'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-11-19T00:00:00+00:00'::TIMESTAMPTZ, 'c6188b856e56298252c03669e369f33c310d562f22de40d4de77830e73110a60'::TEXT, ARRAY[1763]::BIGINT[]),
    (443::BIGINT, 'La verdad a mí me pareció un buen profesor, ayuda si uno pide ayuda y califica bastante fácil.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Tomaría su clase nuevamente']::TEXT[], '2022-11-18T00:00:00+00:00'::TIMESTAMPTZ, '45bf90ad6b3c9075c480d1cc156bef2e02c716a7c37ef7d8ddc167a8a6a981e8'::TEXT, ARRAY[1722]::BIGINT[]),
    (443::BIGINT, 'El profesor hace evaluaciones muy extrañas, no brinda un formato claro de trabajo, él asume que los estudiantes ATI deben saber como se trabaja en Produ. Las presentaciones se hacen en un formato horrible. En fin, no lo recomiendo para nada. (Siendo ATI, en Produ es peor todavía).'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Asistencia obligatoria']::TEXT[], '2022-11-16T00:00:00+00:00'::TIMESTAMPTZ, '9c434590e37de376db3c52ece66daaef4be774f52b312b2d651d4e328441094e'::TEXT, ARRAY[2538]::BIGINT[]),
    (443::BIGINT, 'Es algo intenso. Muchas veces se va por la tangente. Al menos en IO es claro y los exámenes son de acuerdo a lo visto en clases. Deja proyecto y examen para el mismo día.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-11-15T00:00:00+00:00'::TIMESTAMPTZ, 'c19e3d46444c550d2879fd592c2f72b3c1ad9304bd89d35b599f3291081a7793'::TEXT, ARRAY[1746]::BIGINT[]),
    (443::BIGINT, 'El profe es un gran mxlpxrxdx, se le pasa cagando a los estudiantes. Se le desbordan los favoritismos. Hizo un examen rudisimo y al final se puso la mano en el corazón para que pasáramos. La evaluación es complementamente desproporcionada, el proyecto es hacer una tesis de produ,nada que ver con ATI'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-11-12T00:00:00+00:00'::TIMESTAMPTZ, '14f32f45eddcc3822cbe7becc40214c3faf5fc2f6d7a545f10c4695f8655f65e'::TEXT, ARRAY[2538]::BIGINT[]),
    (443::BIGINT, 'Explica bien, la primera procion de la clase es un poco aburrida pues se dispersa en temas que no vienen al caso, pero en general explica bien. Los examenes son sencillos.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-11-06T00:00:00+00:00'::TIMESTAMPTZ, 'bb613f5549b035f42232cef90fa09091238cccb976ea62bb76958a2603b7de2e'::TEXT, ARRAY[1722]::BIGINT[]),
    (443::BIGINT, 'Literalmente manda a hacer una tesis de produ (somos de ati) como trabajo final. Los éxamenes son muy largos y duros, las diapositivas no se entienden nada. Trabajo demasiado desproporcionado a la cantidad de créditos que vale.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Deja trabajos largos']::TEXT[], '2022-10-21T00:00:00+00:00'::TIMESTAMPTZ, '0f1c9e49d23b6244f8687e42b17ee252f2e74b4c45bfe29d5991c743cc742769'::TEXT, ARRAY[2538]::BIGINT[]),
    (443::BIGINT, 'El profe es pura vida, trata de inspirar y hacer la clase llevadera (con ciertas dinámicas y comentarios). Le encanta que el estudiante participe, las evaluaciones son muy similares a los ejemplos vistos en clase'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Inspirador']::TEXT[], '2022-06-27T00:00:00+00:00'::TIMESTAMPTZ, '610e7873869c1be913a77a9436e431dfe5a6e9d8ad3bab60ffb42b899bea2ca7'::TEXT, ARRAY[2536]::BIGINT[]),
    (443::BIGINT, 'Que estrés con el señor, el curso es de ATI y lo da como de producción cuando no sabemos nada de producción. F'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Deja trabajos largos']::TEXT[], '2022-06-26T00:00:00+00:00'::TIMESTAMPTZ, 'd53a660fce795c258b8961bd34e28a05f155255fee0e5dfe1546b72aa73f1ae1'::TEXT, ARRAY[2536]::BIGINT[]),
    (443::BIGINT, 'En clases virtuales era muy malo, grosero y gritaba a los estudiantes, pero los exámenes presenciales son muy sencillos.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Clases largas', 'Muchos proyectos grupales']::TEXT[], '2022-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'c2bac746cba174eabd906fb125cf0d4c493190e680f4e2aa575f4eaebe677728'::TEXT, ARRAY[1736]::BIGINT[]),
    (443::BIGINT, 'Presencial no me parece mal profe, explica bastante y es claro. El proyecto toma tiempo y los exámenes son algo complicados pero nada del otro mundo.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-11T00:00:00+00:00'::TIMESTAMPTZ, '026ae4bd17e860195b8f3475da2460ee34176d2f4fe30bc91b1227e2f2989ac6'::TEXT, ARRAY[1746]::BIGINT[]),
    (443::BIGINT, 'El profe es pura vida. En virtual el mae era muy malo explicando, solamente hacía un ejercicio en clases, pero presencial el mae fue excelente, fue un cambio radical. Se aprende bastante en el curso, si le pides ayuda, te la da. Los exámenes son muy largos y da poco tiempo. Lo recomiendo para IO'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes']::TEXT[], '2022-06-10T00:00:00+00:00'::TIMESTAMPTZ, '6e3c1f1788946aa40c92f2501e7e52d4183acab9613183caf09fc8bc11667070'::TEXT, ARRAY[1746]::BIGINT[]),
    (443::BIGINT, 'Buen profe, quices raros pero parciales fáciles se aprende bastante y explica relativamente bien no le pregunten cosas, deja examen y proyecto para el mismo día'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2022-06-08T00:00:00+00:00'::TIMESTAMPTZ, '48d8c68ccb32ac87efca434674b6f18685c821797c6c1829297d6c14b55a8e36'::TEXT, ARRAY[1722]::BIGINT[]),
    (443::BIGINT, 'profe muy enérgico y la materia la da bastante clara. Sin embargo en evaluaciones aumenta un toque el nivel de los ejercicios. Deja proyecto y examen para el mismo día D:'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-06-08T00:00:00+00:00'::TIMESTAMPTZ, 'b43231c897c0a38a773cb533b127abd627e3e839b49bf5d2348b45409f49418e'::TEXT, ARRAY[1746]::BIGINT[]),
    (443::BIGINT, '(Costos II) El profe es muy buena gente, en mi opinión explica con claridad, es muy necesario participar en la clase y responder las preguntas, si hace los ejercicios que se hicieron en la clase, los del examen se parecen bastante. Lo recomiendo.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Tomaría su clase nuevamente']::TEXT[], '2022-01-17T00:00:00+00:00'::TIMESTAMPTZ, '94390aef2cc4b793921def0a46147117456214bc86ba096eaf8622e4ff158724'::TEXT, ARRAY[1722]::BIGINT[]),
    (443::BIGINT, 'Por lo general la clase solía ser metódica, primero materia y luego ver un video y exponerlo. El proyecto lo califico suave, las clases suelen ser un poco aburridas.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'f04becfa254555480d5dcc417af2af9001147b36769790a274aa29786d40272f'::TEXT, ARRAY[1736]::BIGINT[]),
    (443::BIGINT, 'Como explica el profe hace que uno ponga atención la mayor parte de la clase, muchas veces hay que hacer exposiciones en clase del video que se vio o de algún trabajo que se hace. Los quiz de Socrative no tienen sentido y en los exámenes da poco tiempo por lo que no se puede atener.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'La participación importa']::TEXT[], '2021-12-03T00:00:00+00:00'::TIMESTAMPTZ, '3339205270490355abe6babdff9a4a085982bfa54460cbcbfce82bb0455ff4ea'::TEXT, ARRAY[1736]::BIGINT[]),
    (443::BIGINT, 'Es fácil pasar con él, solo tiene que poner atención en las clases. Hace preguntas sobre la materia que se vio en clases anteriores entonces es necesario tener la materia al día.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Asistencia obligatoria', 'Muchos proyectos grupales']::TEXT[], '2021-12-02T00:00:00+00:00'::TIMESTAMPTZ, '4be16e75119e675e46e35cff6f0a5c71a60dd79c3265b782bd9c06816af5d3bb'::TEXT, ARRAY[1736]::BIGINT[]),
    (443::BIGINT, 'Las clases pueden ser o muy buenas o miserables, depende del ánimo del profe. Las evaluaciones son de internet o el libro. Es bueno ir haciendo los ejercicios en clase para no quedar atrás. El proyecto puede ser un poco volado pero nada imposible (pide un par de soluciones). Es muy pasable virtual.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Asistencia obligatoria', 'Clases largas']::TEXT[], '2021-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'a4be800508e1df9a93c90bc26aec762b0c69c613932d74141321b73c9145fe71'::TEXT, ARRAY[1763]::BIGINT[]),
    (443::BIGINT, '(Virtual) Realmente todos los ejercicios(tareas, exámenes y quices) están en internet. No lo recomiendo, realmente en la clase trata de "Explicar" sin embargo lee mucho, asume que uno entiende o sabe muchas cosas, asista a horas consulta, ahí entenderá mejor las dudas que le surjan.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2021-11-30T00:00:00+00:00'::TIMESTAMPTZ, '41db953e0929fe00ec219fb3804279225181fd8a1997abc4b43601f449a11780'::TEXT, ARRAY[1763]::BIGINT[]),
    (443::BIGINT, 'En geneneral es accesible, aunque a veces se dispersa en las lecciones. Clases aburridas'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-11-03T00:00:00+00:00'::TIMESTAMPTZ, '006d2cd43d914380690323f9ac0904ca6f391654f898855c21cdfcfe59aa5ff5'::TEXT, ARRAY[1736]::BIGINT[]),
    (443::BIGINT, 'El profe grita en clases, la voz es intimidante pero se nota que intenta hacer la clase llevadera. Para los exámenes, las preguntas que salen son las de los Kahoots que hace en el semestre. Es muy fácil pasar y en consulta es otra persona. Le gusta que uno participe en clase.'::TEXT, 10.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-08-01T00:00:00+00:00'::TIMESTAMPTZ, 'e0dcaf48f597f51ed201c87329cb9d2318fd48e1e9ceaf834b43c791d6661698'::TEXT, ARRAY[2538]::BIGINT[]),
    (443::BIGINT, 'No apto para vagos, los va a llevar a dar lo mejor, los obliga a pensar pero nada difícil, denle varias soluciones al proyecto final si no quieren que los mate, buen profe, se aprende como se debe'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas', 'Deja trabajos largos', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-11T00:00:00+00:00'::TIMESTAMPTZ, '1ca398b1183c2f5d1771968e029b39cfff0e75cc01bb61469bba61fea5fe0b7e'::TEXT, ARRAY[1763]::BIGINT[]),
    (443::BIGINT, 'Grita esto no es cierto en audios. Muy brutal, la verdad.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas']::TEXT[], '2021-05-11T00:00:00+00:00'::TIMESTAMPTZ, '5bc9bdb3002993db368bcaa690004eca64760e681718c127c0e7a5d6ad8ed339'::TEXT, ARRAY[1736]::BIGINT[]),
    (443::BIGINT, 'En las consultas usualmente no ayuda mucho, a veces hace comentarios que no agregan a la clase, se memoriza algunos nombres y solo le hace preguntas a esas personas.'::TEXT, 10.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases largas']::TEXT[], '2021-02-06T00:00:00+00:00'::TIMESTAMPTZ, 'd296ff79442663e63e7176a8b27feec11b1b206ca1ef5bbc17eb1cdf8a7dc91e'::TEXT, ARRAY[1763]::BIGINT[]),
    (443::BIGINT, '(Virtual) No enseña bien. Si uno va a consulta lo regaña a uno. Las clases son de 4 horas corridas. Trabajos en grupo. Siempre hace las mismas preguntas en los exámenes o las saca de internet. Es un juega de vivo y pasado con sus comentarios. Entrega de proyecto y examen en un mismo día.'::TEXT, 6.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Clases largas', 'Aspectos de calificación claros']::TEXT[], '2020-08-23T00:00:00+00:00'::TIMESTAMPTZ, 'e24c2412657a708aa6021bcdbc63e3557198de1bda7fb3a20c62e36966f64756'::TEXT, ARRAY[1763]::BIGINT[]),
    (443::BIGINT, '(Virtual) Explica bien, hace quices todas las semanas. Los quices y exámenes son duros (se hace fácil por hacerlo con compás), en general es duro pero pasable a diferencia de la modalidad normal.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchos exámenes', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2020-08-16T00:00:00+00:00'::TIMESTAMPTZ, '3f5292c25bfa329e492bce68b5106d3fc0596b98d213032a62543c602dca25f0'::TEXT, ARRAY[1763]::BIGINT[]),
    (443::BIGINT, 'un juega de vivo el mae.... consiga los examenes de semestres anteriores y listo. Prepárese para que se lo culeen en las primeras evaluaciones pero ya después uno le agarra mas o menos el toque'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-07-24T00:00:00+00:00'::TIMESTAMPTZ, '66c49df3c0810f242f1d3ef4f23241cd576bd54a75343558cfbd4608a85b383b'::TEXT, ARRAY[1736]::BIGINT[]),
    (443::BIGINT, 'Debe de trabajar bastante, no siempre responde con claridad, y muchas veces por estar hablando cosas que no debe al final de la clase lo que da es una verborrea de materia y uno queda bateado porque va demasiado rápido'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-12-02T00:00:00+00:00'::TIMESTAMPTZ, 'bda4be91d887cf4213eb69039f3c93e7086dc52afb11951e61130e0a7ace6a60'::TEXT, ARRAY[1736]::BIGINT[]),
    (443::BIGINT, 'La verdad ni siquiera es bueno meter con él para "aprender más". Metí con él por eso y más bien era un profe que me quería confundir. Cambia la rúbrica con la que dice va a calificar y se burla del estudiante. Quices sin avisar durillos. Al final sí se pasa si uno trabaja, pero se sufre sin sentido'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchos proyectos grupales']::TEXT[], '2019-11-25T00:00:00+00:00'::TIMESTAMPTZ, '5c925e492ed0b6b6010d215a73c763ca7e29beff74afa78a2613b1cf0c3a1cc6'::TEXT, ARRAY[1736]::BIGINT[]),
    (443::BIGINT, 'No lo recomiendaría, deja trabajos con una rúbrica y los califica con otra, se pone tenso en clase si uno le hace preguntas de la materia, hace quices duros sin aviso previo. Mejor con Harold de una vez.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Asistencia obligatoria', 'Aspectos de calificación claros']::TEXT[], '2019-10-11T00:00:00+00:00'::TIMESTAMPTZ, '458801c8128ae6b223411819c689bb317b63309dfa3bdd6bb1339bd02e95265c'::TEXT, ARRAY[1736]::BIGINT[]),
    (443::BIGINT, 'Si mete un curso con él va a necesitar dedicarle su tiempo para estudiar y practicar, no es un profe fácil pero si se aprende bastante. Le gustan los trabajos bien hechos y si le pone si pasa cualquiera de los 3 cursos.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos', 'Exámenes retadores']::TEXT[], '2019-06-29T00:00:00+00:00'::TIMESTAMPTZ, '6e90ef999a795b860ee4743ee3e8dbcbe9d8a08eecffdf40141d6a89dfd13876'::TEXT, ARRAY[1763, 1736]::BIGINT[]),
    (443::BIGINT, 'Para este curso simplemente EVÍTELO (me lo va a agradecer); califica binomial, hace muy pocos quices, no deja tareas, es inflexible, deja proyecto final y último examen el mismo día, agarra la mitad de la clase para hablar cosas triviales, entre otras cosas.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2019-05-24T00:00:00+00:00'::TIMESTAMPTZ, '6a27bca1fdb4817340e46d00f4b95e00aad0c11657093bebf8e97d26a5858b26'::TEXT, ARRAY[1763]::BIGINT[]),
    (443::BIGINT, 'Uno de los peores profesores con los que he tenido la desdicha de toparme en la escuela Una verdadera lástima que no sepa enseñar Literalmente mejor uno lo ignora mientras da la clase y mejor tratar de entender solo Lástima que sea mejor que la única otra opción para el curso'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas']::TEXT[], '2019-03-28T00:00:00+00:00'::TIMESTAMPTZ, '9b79163585a2ac31350798a65665c747878bade0d8ba564345f1155116d79e53'::TEXT, ARRAY[1763]::BIGINT[]),
    (443::BIGINT, 'Si se aprende. Tiene preferencias situación bastante molesta.'::TEXT, 6.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2018-11-29T00:00:00+00:00'::TIMESTAMPTZ, 'c4e611a7ab7bde9622693067ed3196ffc2b2115c72fb3860523955d242176338'::TEXT, ARRAY[1763]::BIGINT[]),
    (443::BIGINT, 'El profe explica muy bien y hace muchos ejemplos en clase. Hay quices todas las semanas y los examenes pueden ser dificiles pero no imposibles. Le gustan los trabajos bien hechos. Recomendado si quiere aprender'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-11-29T00:00:00+00:00'::TIMESTAMPTZ, '3e6df8746afe56303c4f8b42e4e3720122d17cf49ac753db5fe17f014c40130c'::TEXT, ARRAY[1746]::BIGINT[]),
    (443::BIGINT, 'Un profesor que le gusta los trabajos bien hechos, para explicar no es tan bueno, pero si le pone al final él le ayuda. Él sabe muchísimo y trata de que el estudiante haga su mejor esfuerzo. Recomendado.'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-23T00:00:00+00:00'::TIMESTAMPTZ, 'ded996b5f11514d5ebe7082f1bc39f9ae7a1eb6638f861baee6a3561a1386189'::TEXT, ARRAY[1736]::BIGINT[]),
    (443::BIGINT, 'Explica lo que realmente evalúa, es un poco duro el curso pero ayuda si ve que uno le pone.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-12T00:00:00+00:00'::TIMESTAMPTZ, '737133dcf62a4a2c2b426bfa420a44ae8007eaa763eac0b1c54254fc9c133304'::TEXT, ARRAY[1763]::BIGINT[]),
    (443::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-01-14T00:00:00+00:00'::TIMESTAMPTZ, '3d1c41ada4f360b64f44d69d149158bd271efbcbdcb111acee8d9ceaea07ae15'::TEXT, ARRAY[1831]::BIGINT[]),
    (443::BIGINT, 'es grosero'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-12-29T00:00:00+00:00'::TIMESTAMPTZ, 'de55ca80f1fcb1c202e0204d6b494b0cb2151a9f49ce0a21218f4f0abd9ec273'::TEXT, ARRAY[1736]::BIGINT[]),
    (443::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2017-12-06T00:00:00+00:00'::TIMESTAMPTZ, 'f8a81f59ada34bd5011fbe6cbb22820bf15e440c32329b0ba5a8896be7b775cf'::TEXT, ARRAY[1736]::BIGINT[]),
    (443::BIGINT, 'Cuando le tomas el ritmo es muy bueno, se interesa mucho por los estudiantes y es muy comprometido para ayudar en consulta.'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-10-29T00:00:00+00:00'::TIMESTAMPTZ, '8929893926ffc641f13965d8f97a01df0af9160dc70e1a6b57b4c6ea57311d80'::TEXT, ARRAY[1736]::BIGINT[]),
    (443::BIGINT, 'Era bastante interesante, lo malo es que explicaba lo importante en la ultima media hora de clase pero en general un profe muy accesible y se interesa en los estudiantes'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-30T00:00:00+00:00'::TIMESTAMPTZ, '758d70fa125ce4eeee6c9c071ead8086e654e4673a10827ac9942ac44132b0e2'::TEXT, ARRAY[1736]::BIGINT[]),
    (443::BIGINT, 'Cuesta entenderle al principio pero es cosa de agarrale el ritmo. Califica rudo, es exigente, sin embargo se aprende bastante.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, '90412c5565fcc85f8b9ddca29f8196bc5b209c4d523b9293ef3e348da76a185f'::TEXT, ARRAY[1736]::BIGINT[]),
    (443::BIGINT, 'Es un buen profe, le da mucha importancia al proyecto'::TEXT, 8.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Deja trabajos largos']::TEXT[], '2017-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'f84bcdbb85a79c979a94e91779b040f11b058170c0fae800ffe1d69a028ff9d4'::TEXT, ARRAY[1736]::BIGINT[]),
    (443::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Tomaría su clase nuevamente']::TEXT[], '2017-05-17T00:00:00+00:00'::TIMESTAMPTZ, '9f13d70ed44197cc51878cc75b7638552521de6396ef2938df65e9f3e1056675'::TEXT, ARRAY[1736]::BIGINT[]),
    (443::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Respetado por los estudiantes', 'Deja trabajos largos']::TEXT[], '2016-06-27T00:00:00+00:00'::TIMESTAMPTZ, 'b846e93931e32a28c6f3df31ba142df76254bfe02d88cf8b74226255eb3ab412'::TEXT, ARRAY[1736]::BIGINT[]),
    (443::BIGINT, 'No habían horas consulta por q decía que se le dificultaba tener tiempo para ese espacio, nos dio el número de teléfono para aclarar dudas por ahí y nunca contestaba nada. Exámenes con contenido poco similar a las prácticas de clase. Clases demasiado rápidas, muy buena persona, como profe no tanto.'::TEXT, 8.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Muchos proyectos grupales']::TEXT[], '2016-06-07T00:00:00+00:00'::TIMESTAMPTZ, '46fb994d68e88c334d785ffcc77551b3746df0993c25168adc671f236ef9037a'::TEXT, ARRAY[1722]::BIGINT[]),
    (443::BIGINT, 'Ninguno'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-05-28T00:00:00+00:00'::TIMESTAMPTZ, '3fb18c372991f055be3aa3ea86fbb6c1a8f99279be0d210dd37062983459509a'::TEXT, ARRAY[1763]::BIGINT[]),
    (443::BIGINT, 'Es un profe muy aburrido, solo lee y lee presentaciones. Aveces va muy rápido y uno se queda botado. Es buena persona. Exámenes normales.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Exámenes retadores', 'Clases largas', 'Deja trabajos largos']::TEXT[], '2016-02-10T00:00:00+00:00'::TIMESTAMPTZ, '1adfb8956791ea05bf54b678d9f3b8c9ad780261efee301a986f03849f9dc52d'::TEXT, ARRAY[1736]::BIGINT[]),
    (443::BIGINT, 'Ninguno'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-16T00:00:00+00:00'::TIMESTAMPTZ, 'd1fdd1b7100139acdcb728f93b030b31b342456d38603158a780d85d9fbdfc72'::TEXT, ARRAY[1736]::BIGINT[]),
    (443::BIGINT, 'Ninguno'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-26T00:00:00+00:00'::TIMESTAMPTZ, '8592198832d21cef6c4b1b9b2ab1d7ee2e60a71eee40f6164dfbafb082c22bf1'::TEXT, ARRAY[1763]::BIGINT[]),
    (443::BIGINT, 'Como persona es genial,es ordenado, no califica duro, sabe mucho y lo mejor, sabe transmitir ese conocimiento.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-11-25T00:00:00+00:00'::TIMESTAMPTZ, '3a6c3b2e42a0566c05191120b2e4c264bf7d3733e3ae00b16c33969555cf1445'::TEXT, ARRAY[1736]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
